function q(v) {
  if (v === null || v === undefined || v === '') return 'null';
  return "'" + String(v).replace(/'/g, "''") + "'";
}
function semAcento(s) {
  return String(s === null || s === undefined ? '' : s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
}

const bruto = $input.first().json || {};
const p = bruto.body ? bruto.body : bruto;

const fromMe = p.fromMe === true || p.fromMe === 'true';
const ehGrupo = p.isGroup === true || p.isGroup === 'true';
const ehStatus = p.isStatusReply === true || p.isStatusReply === 'true';
const telefone = String(p.phone || p.from || '').replace(/\D/g, '');

if (fromMe || ehGrupo || ehStatus || !telefone) {
  console.log('callback ignorado: fromMe=' + fromMe + ' grupo=' + ehGrupo + ' status=' + ehStatus + ' telefone=' + telefone);
  return [];
}

let texto = '';
if (p.text && p.text.message) texto = String(p.text.message);
else if (typeof p.message === 'string') texto = p.message;
else if (p.buttonsResponseMessage && p.buttonsResponseMessage.message) texto = String(p.buttonsResponseMessage.message);
else if (p.listResponseMessage && p.listResponseMessage.message) texto = String(p.listResponseMessage.message);

let tipoMidia = '';
if (!texto) {
  if (p.audio) tipoMidia = 'audio';
  else if (p.image) tipoMidia = 'imagem';
  else if (p.document) tipoMidia = 'documento';
  else if (p.video) tipoMidia = 'video';
  else tipoMidia = 'nao identificado';
  texto = '[o lead enviou ' + tipoMidia + ' em vez de texto]';
}

const t = semAcento(texto).trim();
const pediuSair = /^(sair|parar|pare|stop|remover|descadastrar|cancelar)\b/.test(t)
  || /\bsair\b/.test(t)
  || /(nao|n\u00e3o)\s+(quero|desejo)\s+(mais\s+)?(receber|nada|contato|mensagens)/.test(t)
  || /(me\s+(remove|tire|exclua)|para\s+de\s+(mandar|me\s+mandar)|nao\s+me\s+mande)/.test(t);

const sql = 'with upd as ('
  + 'update disparo.leads set status = case when status in (' + q('novo') + ', ' + q('enviado') + ') then ' + q('respondeu') + ' else status end, '
  + 'ultimo_contato = now(), atualizado_em = now() where telefone = ' + q(telefone) + ' returning 1'
  + '), ins as ('
  + 'insert into disparo.mensagens (telefone, direcao, conteudo, status) values (' + q(telefone) + ', ' + q('in') + ', ' + q(texto) + ', ' + q('recebida') + ') returning 1'
  + '), cfg as (select coalesce(jsonb_object_agg(chave, valor), ' + q('{}') + '::jsonb) as config from disparo.config) '
  + 'select cfg.config, l.telefone as lead_telefone, l.nome, l.nome_cliente, l.papel, l.cidade, l.regiao, l.obras, l.multi_obra, '
  + 'l.metragem, l.inicio, l.termino, l.estado, l.pf_pj, l.piscina, l.destinacao, l.pre_moldados, l.concreto_usinado, '
  + 'l.possivel_decadencia, l.receptividade, l.perfil, l.status, '
  + 'coalesce((select jsonb_agg(jsonb_build_object(' + q('direcao') + ', m.direcao, ' + q('conteudo') + ', m.conteudo, ' + q('em') + ', to_char(m.criado_em at time zone ' + q('America/Sao_Paulo') + ', ' + q('DD/MM HH24:MI') + ')) order by m.criado_em) '
  + 'from (select * from disparo.mensagens where telefone = ' + q(telefone) + ' order by criado_em desc limit 20) m), ' + q('[]') + '::jsonb) as historico '
  + 'from cfg left join disparo.leads l on l.telefone = ' + q(telefone) + ';';

return [{
  json: {
    telefone: telefone,
    texto: texto,
    tipo_midia: tipoMidia,
    nome_whatsapp: p.senderName || p.chatName || '',
    pediu_sair: pediuSair,
    recebido_em: $now.setZone('America/Sao_Paulo').toISO(),
    sql: sql
  }
}];

const ctx = $input.first().json || {};
const msg = $('Normalizar Mensagem Recebida').first().json || {};
const cfg = ctx.config || {};

let rota = 'atender';
let motivo = '';
if (!ctx.lead_telefone) {
  rota = 'ignorar';
  motivo = 'telefone nao esta na base de leads';
} else if (ctx.status === 'optout') {
  rota = 'ignorar';
  motivo = 'lead ja pediu optout';
} else if (ctx.status === 'transferido') {
  rota = 'ignorar';
  motivo = 'lead ja transferido para o especialista';
} else if (msg.pediu_sair) {
  rota = 'optout';
  motivo = 'lead pediu para sair';
}

function ou(v, padrao) {
  const s = v === null || v === undefined ? '' : String(v).trim();
  return s ? s : padrao;
}

const obras = Array.isArray(ctx.obras) ? ctx.obras : [];
const linhasObras = obras.map(function (o) {
  return '- obra ' + ou(o.id_obra, 'sem id') + ': ' + ou(o.endereco, 'endereco nao informado')
    + ', fase ' + ou(o.fase, 'nao informada') + ', ' + ou(o.metragem, 'metragem nao informada') + ' m2'
    + ', inicio ' + ou(o.inicio, 'nao informado') + ', termino ' + ou(o.termino, 'nao informado');
}).join('\n');

const historico = Array.isArray(ctx.historico) ? ctx.historico : [];
const linhasHistorico = historico.map(function (h) {
  return (h.direcao === 'out' ? 'Ana' : 'Lead') + ' (' + ou(h.em, '') + '): ' + ou(h.conteudo, '');
}).join('\n');

const coleta = [
  ['metragem', ctx.metragem],
  ['inicio', ctx.inicio],
  ['termino', ctx.termino],
  ['estado', ctx.estado],
  ['pf_pj', ctx.pf_pj],
  ['piscina', ctx.piscina],
  ['destinacao', ctx.destinacao],
  ['pre_moldados', ctx.pre_moldados],
  ['concreto_usinado', ctx.concreto_usinado]
];
const jaTem = coleta.filter(function (c) { return ou(c[1], '') !== ''; }).map(function (c) { return c[0] + '=' + c[1]; });
const faltam = coleta.filter(function (c) { return ou(c[1], '') === ''; }).map(function (c) { return c[0]; });

const contexto = 'DADOS DO LEAD (do relatorio, ja conhecidos)\n'
  + 'Nome do contato: ' + ou(ctx.nome, 'nao informado') + '\n'
  + 'Cliente no relatorio: ' + ou(ctx.nome_cliente, 'nao informado') + '\n'
  + 'Papel na obra: ' + ou(ctx.papel, 'nao informado') + '\n'
  + 'Cidade: ' + ou(ctx.cidade, 'nao informada') + ' | Regiao: ' + ou(ctx.regiao, 'nao informada') + '\n'
  + 'Metragem: ' + ou(ctx.metragem, 'nao informada') + ' | Inicio: ' + ou(ctx.inicio, 'nao informado') + ' | Termino: ' + ou(ctx.termino, 'nao informado') + '\n'
  + 'Obras:\n' + (linhasObras || '- sem obras registradas') + '\n\n'
  + 'DADOS JA CONFIRMADOS COM O LEAD: ' + (jaTem.length ? jaTem.join(', ') : 'nenhum') + '\n'
  + 'AINDA FALTA CONFIRMAR: ' + (faltam.length ? faltam.join(', ') : 'nada, pode encaminhar para o especialista') + '\n\n'
  + 'HISTORICO DA CONVERSA (mais antigo primeiro)\n' + (linhasHistorico || '- sem mensagens anteriores') + '\n\n'
  + 'MENSAGEM NOVA DO LEAD AGORA:\n' + ou(msg.texto, '');

return [{
  json: {
    rota: rota,
    motivo: motivo,
    telefone: msg.telefone,
    texto_lead: msg.texto,
    nome: ou(ctx.nome, ou(msg.nome_whatsapp, '')),
    nome_cliente: ctx.nome_cliente,
    cidade: ctx.cidade,
    regiao: ctx.regiao,
    obras: obras,
    possivel_decadencia: ctx.possivel_decadencia === true,
    status_atual: ctx.status,
    faltam: faltam,
    config: cfg,
    test_mode: String(cfg.TEST_MODE || 'true').toLowerCase() === 'true',
    numero_teste: String(cfg.NUMERO_TESTE || '5565999725622').replace(/\D/g, ''),
    contexto: contexto
  }
}];

function q(v) {
  if (v === null || v === undefined || v === '') return 'null';
  return "'" + String(v).replace(/'/g, "''") + "'";
}
function ou(v, padrao) {
  const s = v === null || v === undefined ? '' : String(v).trim();
  return s ? s : padrao;
}
function sn(v) {
  const s = String(v === null || v === undefined ? '' : v).toLowerCase();
  if (!s) return 'nao informado';
  if (s.indexOf('sim') === 0 || s === 's' || s === 'true') return 'SIM';
  if (s.indexOf('nao') === 0 || s.indexOf('n\u00e3o') === 0 || s === 'n' || s === 'false') return 'NAO';
  return String(v);
}

const ctx = $('Rotear Conversa').first().json || {};
const bruta = $input.first().json || {};
const out = bruta.output ? bruta.output : bruta;
const dados = out.dados || {};

const telefone = String(ctx.telefone || '').replace(/\D/g, '');
const respostaLead = ou(out.resposta, 'Perfeito, já anotei aqui. Qualquer dúvida me chama.');

const optout = out.optout === true || out.optout === 'true';
const handoff = !optout && (out.handoff === true || out.handoff === 'true');
let status = 'coletando';
if (optout) status = 'optout';
else if (handoff) status = 'qualificado';

let respostaEnvio = respostaLead;
let telefoneEnvio = telefone;
if (ctx.test_mode) {
  telefoneEnvio = ctx.numero_teste;
  respostaEnvio = '[TESTE | resposta da Ana para ' + ou(ctx.nome, 'lead') + ' | tel real: ' + telefone + ']\n' + respostaLead;
}

const campos = [
  ['metragem', dados.metragem],
  ['inicio', dados.inicio],
  ['termino', dados.termino],
  ['estado', dados.estado],
  ['pf_pj', dados.pf_pj],
  ['piscina', dados.piscina],
  ['destinacao', dados.destinacao],
  ['pre_moldados', dados.pre_moldados],
  ['concreto_usinado', dados.concreto_usinado]
];
const sets = [];
for (const c of campos) {
  const valor = ou(c[1], '');
  if (valor) sets.push(c[0] + ' = ' + q(valor));
}
sets.push('receptividade = coalesce(' + q(ou(out.receptividade, '')) + ', receptividade)');
sets.push('perfil = coalesce(' + q(ou(out.perfil, '')) + ', perfil)');
sets.push('status = ' + q(status));
sets.push('ultimo_contato = now()');
sets.push('atualizado_em = now()');

const sql = 'with m as ('
  + 'insert into disparo.mensagens (telefone, direcao, conteudo, status) values (' + q(telefone) + ', ' + q('out') + ', ' + q(respostaLead) + ', ' + q('enviada') + ') returning 1'
  + '), u as ('
  + 'update disparo.leads set ' + sets.join(', ') + ' where telefone = ' + q(telefone) + ' returning 1'
  + ') select ' + q(status) + ' as status_novo, ' + q(telefone) + ' as telefone;';

const sqlTransferido = 'update disparo.leads set status = ' + q('transferido')
  + ', atualizado_em = now() where telefone = ' + q(telefone) + ' returning telefone, status;';

const obras = Array.isArray(ctx.obras) ? ctx.obras : [];
const linhasObras = obras.map(function (o) {
  return '  . obra ' + ou(o.id_obra, 'sem id') + ': ' + ou(o.endereco, 'endereco nao informado')
    + ' | fase ' + ou(o.fase, 'nao informada') + ' | ' + ou(o.metragem, 'sem metragem') + ' m2'
    + ' | ' + ou(o.inicio, 'inicio nao informado') + ' a ' + ou(o.termino, 'termino nao informado');
}).join('\n');

const preMoldados = sn(dados.pre_moldados);
const usinado = sn(dados.concreto_usinado);
const sinais = [];
if (preMoldados === 'SIM') sinais.push('pre-moldados de concreto comprados prontos (verificar art. 26 par. 2, exige NF e instalacao do fabricante)');
if (usinado === 'SIM') sinais.push('concreto usinado (item de reducao separado)');
if (ctx.possivel_decadencia) sinais.push('obra com inicio ha mais de 5 anos (avaliar decadencia)');

const resumoInterno = 'LEAD QUALIFICADO | WM Assessoria\n'
  + 'Nome: ' + ou(ctx.nome, 'nao informado') + (ou(ctx.nome_cliente, '') && ctx.nome_cliente !== ctx.nome ? ' (cliente no relatorio: ' + ctx.nome_cliente + ')' : '') + '\n'
  + 'Telefone: ' + telefone + '\n'
  + 'Cidade/Regiao: ' + ou(ctx.cidade, 'nao informada') + ' / ' + ou(ctx.regiao, 'nao informada') + '\n'
  + 'Obras:\n' + (linhasObras || '  . sem obras registradas') + '\n'
  + '\nDADOS DA SIMULACAO\n'
  + '  Metragem: ' + ou(dados.metragem, 'nao informada') + '\n'
  + '  Inicio: ' + ou(dados.inicio, 'nao informado') + ' | Termino: ' + ou(dados.termino, 'nao informado') + '\n'
  + '  Estado: ' + ou(dados.estado, 'nao informado') + '\n'
  + '  PF ou PJ: ' + ou(dados.pf_pj, 'nao informado') + '\n'
  + '  Piscina: ' + sn(dados.piscina) + '\n'
  + '  Destinacao: ' + ou(dados.destinacao, 'nao informada') + '\n'
  + '  Pre-moldados: ' + preMoldados + '\n'
  + '  Concreto usinado: ' + usinado + '\n'
  + '\nLEITURA DO LEAD\n'
  + '  Receptividade: ' + ou(out.receptividade, 'nao classificada') + '\n'
  + '  Perfil: ' + ou(out.perfil, 'nao classificado') + '\n'
  + '\nALERTAS INTERNOS\n'
  + '  Possivel decadencia: ' + (ctx.possivel_decadencia ? 'SIM' : 'NAO') + '\n'
  + '  Sinais de reducao: ' + (sinais.length ? sinais.join('; ') : 'nenhum identificado ainda');

let resumoEnvio = resumoInterno;
if (ctx.test_mode) resumoEnvio = '[TESTE | resumo interno que iria para o numero 2]\n' + resumoInterno;

return [{
  json: {
    telefone: telefone,
    telefone_envio: telefoneEnvio,
    resposta_lead: respostaLead,
    resposta_envio: respostaEnvio,
    status_novo: status,
    handoff: handoff,
    optout: optout,
    receptividade: out.receptividade || null,
    perfil: out.perfil || null,
    test_mode: ctx.test_mode === true,
    numero_teste: ctx.numero_teste,
    resumo_interno: resumoEnvio,
    sql: sql,
    sql_transferido: sqlTransferido
  }
}];

function q(v) {
  if (v === null || v === undefined || v === '') return 'null';
  return "'" + String(v).replace(/'/g, "''") + "'";
}

const ctx = $input.first().json || {};
const telefone = String(ctx.telefone || '').replace(/\D/g, '');
const primeiro = String(ctx.nome || '').trim().split(/\s+/)[0] || '';
const saudacaoNome = primeiro ? (', ' + primeiro.charAt(0).toUpperCase() + primeiro.slice(1).toLowerCase()) : '';

const resposta = 'Tudo bem' + saudacaoNome + '! Já removi seu contato da nossa lista e não vou mais te chamar. Se um dia precisar resolver o INSS de alguma obra, é só me mandar mensagem. Abraço!';

let telefoneEnvio = telefone;
let respostaEnvio = resposta;
if (ctx.test_mode) {
  telefoneEnvio = ctx.numero_teste;
  respostaEnvio = '[TESTE | optout de ' + (ctx.nome || 'lead') + ' | tel real: ' + telefone + ']\n' + resposta;
}

const sql = 'with m as ('
  + 'insert into disparo.mensagens (telefone, direcao, conteudo, status) values (' + q(telefone) + ', ' + q('out') + ', ' + q(resposta) + ', ' + q('enviada') + ') returning 1'
  + '), u as ('
  + 'update disparo.leads set status = ' + q('optout') + ', ultimo_contato = now(), atualizado_em = now() where telefone = ' + q(telefone) + ' returning 1'
  + ') select ' + q('optout') + ' as status_novo, ' + q(telefone) + ' as telefone;';

return [{
  json: {
    telefone: telefone,
    telefone_envio: telefoneEnvio,
    resposta_lead: resposta,
    resposta_envio: respostaEnvio,
    sql: sql
  }
}];
